{"description":"review-and-present","code":"await tools.write({file_path:"final.md",content:"第1集\n1-1 门口 日 内\n人物：声音A、声音B\n声音A：旧床不要拆。\n▲床保持完整，两人站在门口。\n声音B：还没同意。\n"});
const source=JSON.parse(await tools.manuscript_revision({"action":"source_fidelity","task":"核对明确映射的缓存原图和保存ASR，不声称原音或全片已核验。","documents":[{"role":"current","path":"final.md"}],"video_sources":[{"review_id":"binding-video-source","start_seconds":0,"end_seconds":6,"draft_lines":{"start":1,"end":6},"frame_ids":["F00001","F00002"]}]}));
const text=JSON.parse(await tools.manuscript_revision({"action":"continuity","task":"核对最终稿全部提取正文的因果衔接，不编辑文件。","documents":[{"role":"current","path":"final.md"}]}));
const delivery = JSON.parse(await tools.manuscript_revision({"action":"delivery","source_mode":"video","delivery_mode":"reviewed","candidate_paths":["final.md"]}));
await tools.present({files:[{path:"final.md",description:delivery.files[0].label}]});
return {source:source.status,text:text.status,label:delivery.files[0].label};"}

